// One engine instance per file. No workbook model crosses the worker boundary.
// @ts-ignore generated by wasm-bindgen
import init, { Engine } from "../engine/pkg/canvas_xlsx_engine.js";
let engine: any;
let ready: Promise<any>;
self.onmessage = async (event: MessageEvent) => {
  const { id, op, ...args } = event.data;
  try {
    if (op === "load") {
      ready ??= init({ module_or_path: args.wasmBytes });
      await ready;
      engine?.free();
      engine = new Engine(new Uint8Array(args.bytes));
      postMessage({
        id,
        result: JSON.parse(engine.request(JSON.stringify({ op: "info" }))),
      });
      return;
    }
    if (!engine) throw new Error("ブックの読み込みが完了していません");
    if (op === "save") {
      const bytes = engine.save();
      postMessage({ id, result: bytes }, [bytes.buffer]);
      return;
    }
    postMessage({
      id,
      result: JSON.parse(engine.request(JSON.stringify({ op, ...args }))),
    });
  } catch (e) {
    postMessage({ id, error: String(e) });
  }
};
